#!/usr/bin/env python3
"""Merge v2 SIMD/SIMT board measurements into the model-v2 dense dataset.

The dataset intentionally stores only *white-box topology facts that can be
derived from (mode, block, stride)* plus the measured target.  Candidate
bank/sector features are generated by the fitting script, not hardcoded here.
"""
from __future__ import annotations

import csv
import json
import math
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
HERE = SCRIPT_DIR.parent  # pre-explore root (scripts/ lives directly under it)
RES = HERE / "results"
OUT_DIR = RES / "model_v2"
OUT_CSV = OUT_DIR / "dataset.csv"

SYS_CNT_NS = 1.00008
ELEM_BYTES = 4
LINE_BYTES = 128
MTE_MAX_CMD_BYTES = 512
LANES_PER_WARP = 32

SOURCES = [
    ("simd", "simd_base", RES / "board_v2_simd/frequency_retry_results.json"),
    ("simd", "simd_more", RES / "board_v2_simd_more_blocks/frequency_retry_results.json"),
    ("simt", "simt_base", RES / "board_v2_simt/simt_frequency_retry_results.json"),
    ("simt", "simt_more", RES / "board_v2_simt_more_blocks/simt_frequency_retry_results.json"),
]

FIELDS = [
    "mode", "block", "stride", "elem_bytes",
    "path", "n_cmd", "fetch_bytes", "K", "L",
    "ns_size", "stride_bytes",
    "target_ns", "target_kind",
    "aicore_freq_before_mhz", "aicore_freq_after_mhz",
    "noload_cycles_median", "normalization_factor",
    "source_json", "valid",
]


def simd_target_ns(case):
    raw = case.get("normalized_delta")
    if raw is None:
        raw = float(case.get("delta_median", 0.0)) * float(case.get("normalization_factor", 1.0))
    return float(raw) * SYS_CNT_NS


def simt_target_ns(case):
    raw = case.get("event_slope_normalized_ns_per_iter")
    if raw is None:
        raw = float(case.get("event_slope_ns_per_iter", 0.0)) * float(case.get("normalization_factor", 1.0))
    return float(raw)


def derive_path(mode, stride):
    if mode == "simd":
        return "simd_wide" if stride in (1, 2) else "simd_gather"
    return "simt"


def simd_facts(block, stride, elem_bytes=ELEM_BYTES):
    if stride in (1, 2):
        fetch_bytes = block * stride * elem_bytes
        n_cmd = max(1, math.ceil(fetch_bytes / MTE_MAX_CMD_BYTES))
        return n_cmd, fetch_bytes
    return block, block * elem_bytes


def simt_facts(block, stride, elem_bytes=ELEM_BYTES):
    stride_bytes = stride * elem_bytes
    # f32 stride==1 lane-vectorizes two elements per thread; this matches both
    # CAModel and the current lowering.  Other strides are one element/lane.
    vector_elements = max(1, 8 // elem_bytes) if stride == 1 else 1
    k = max(1, math.ceil(block / (LANES_PER_WARP * vector_elements)))
    if stride_bytes >= LINE_BYTES:
        lines = block
    else:
        lines = ((block - 1) * stride_bytes) // LINE_BYTES + 1
    return k, lines


def read_cases(mode, source_name, path):
    if not path.exists():
        return []
    payload = json.loads(path.read_text())
    cases = payload.get("cases", [])
    out = []
    for case in cases:
        if not case.get("valid", False):
            continue
        block = int(case["block"])
        stride = int(case["stride"])
        elem_bytes = ELEM_BYTES
        if mode == "simd":
            n_cmd, fetch_bytes = simd_facts(block, stride, elem_bytes)
            k = ""
            lines = ""
            target = simd_target_ns(case)
            target_kind = "simd_single_cold"
            noload = case.get("noload_cycles_median")
        else:
            n_cmd = ""
            fetch_bytes = ""
            k, lines = simt_facts(block, stride, elem_bytes)
            target = simt_target_ns(case)
            target_kind = "simt_rotate_iter"
            noload = ""
        out.append({
            "mode": mode,
            "block": block,
            "stride": stride,
            "elem_bytes": elem_bytes,
            "path": derive_path(mode, stride),
            "n_cmd": n_cmd,
            "fetch_bytes": fetch_bytes,
            "K": k,
            "L": lines,
            # N*S tile footprint in elements; useful as a dataset-side diagnostic.
            "ns_size": block * stride,
            "stride_bytes": stride * elem_bytes,
            "target_ns": target,
            "target_kind": target_kind,
            "aicore_freq_before_mhz": case.get("aicore_freq_before_mhz"),
            "aicore_freq_after_mhz": case.get("aicore_freq_after_measure_mhz"),
            "noload_cycles_median": noload,
            "normalization_factor": case.get("normalization_factor", 1.0),
            "source_json": source_name,
            "valid": True,
        })
    return out


def main():
    merged = {}
    order = []
    for mode, source_name, path in SOURCES:
        cases = read_cases(mode, source_name, path)
        print(f"{source_name}: {len(cases)} valid cases from {path}")
        for row in cases:
            key = (row["mode"], int(row["block"]), int(row["stride"]))
            if key in merged:
                # Later, more-specific files win; currently the matrices are disjoint.
                merged[key] = row
            else:
                merged[key] = row
                order.append(key)
    rows = [merged[k] for k in order]
    # Sort for deterministic output: mode/path, block, stride.
    rows.sort(key=lambda r: (r["mode"], r["path"], int(r["block"]), int(r["stride"])))
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    with OUT_CSV.open("w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDS, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)
    print(f"wrote {OUT_CSV} ({len(rows)} rows)")


if __name__ == "__main__":
    main()
